// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 depositAmount, address actor) public {
        depositAmount = bound(depositAmount, 1, 1 ether);
        vm.assume(actor != address(this));

        vm.deal(actor, 1 ether);
        vm.deal(address(this), depositAmount);
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "initial deposit failed");

        uint256 before = address(c).balance;

        bool ok;
        vm.prank(actor);
        try c.withdraw(depositAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || address(c).balance == before);
    }
}
